<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\UserFederatedIdentitySubjectVO;

trait UserFederatedIdentitySubjectAccessor
{
    private UserFederatedIdentitySubjectVO $_subject;
    public function getSubject(): string
    {
        return $this->_subject->value();
    }
    public function subject(): UserFederatedIdentitySubjectVO
    {
        return $this->_subject;
    }
    public function isSubjectChanged(?self $original = null): bool
    {
        return !$this->_subject->equals($original?->_subject);
    }
    public function withSubject(UserFederatedIdentitySubjectVO|string $subject): self
    {
        $copy = clone $this;
        $copy->_subject = UserFederatedIdentitySubjectVO::from($subject);
        return $copy;
    }
}
